pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space below 10 units is difficult to reuse for the expected item
    // range, so penalize it sharply. Smaller gaps are worse.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 18.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 4.0;
    }

    // Preserve flexible capacity when the current placement would leave a
    // conspicuously poor remainder.
    if post_residual > 0 && post_residual < item_size {
        score += (item_size - post_residual) as f64 * 2.5;
    }

    // Favor a nearly filled bin, with diminishing returns for exact closure.
    if post_residual == 0 {
        score -= 30.0;
    } else {
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // If this is the last fitting opportunity, avoid creating another poorly
    // reusable residual; otherwise a little dead space is acceptable.
    if fitting_bins_count <= 1 && post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64) * 25.0;
    }

    // New bins are inherently less desirable than an existing usable bin,
    // but reduce this disadvantage when the stream has many active bins and
    // the average residual indicates substantial unused capacity pressure.
    if bin_residual == bin_capacity {
        score += 12.0;
        score += open_bins_count as f64 * 0.35;
        score -= mean_residual * 0.08;
    } else {
        // Encourage consolidation when many bins are open, especially when
        // the current bin is substantially worse than the average.
        score += open_bins_count as f64 * 0.20;
        score -= (mean_residual - post_residual as f64) * 0.12;
    }

    // Look ahead one item: retain room for the next item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Near the end of the stream, prioritize exact closure and avoid wasting
    // residual capacity that can no longer be filled efficiently.
    let progress = if total_items == 0 {
        1.0
    } else {
        step_index as f64 / total_items as f64
    };
    if progress > 0.80 {
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.max(0.0);
    let progress = if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 };

    let dead_fraction = if post == 0.0 { 1.0 } else if post < next && next > 0.0 { 1.0 + (next - post) / capacity } else { 0.0 };
    score += dead_fraction * 18.0;

    let modulo_class = (item_size as usize) % 4;
    score += (modulo_class as f64 - 1.5).abs() * 1.5;

    let post_tenths = (post / 10.0).floor();
    let next_tenths = (next / 10.0).floor();
    if next > 0.0 && post < next {
        score += (next_tenths - post_tenths).abs() * 2.0;
    }

    let utilization = (item / capacity).clamp(0.0, 1.0);
    score += utilization * 5.0;
    score -= (post / capacity).min(1.0) * 3.0;

    if mean > 0.0 {
        score += ((post - mean) / capacity).abs() * 4.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 12.0;
    }

    if next == 0.0 {
        score += progress * 4.0;
    } else {
        score -= (next / capacity).min(1.0) * 2.0;
    }

    if open_bins_count == 0 && bin_residual == bin_capacity {
        score -= 20.0;
    }

    if bin_residual == bin_capacity {
        score += 8.0;
        if next > 0.0 && item < next {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_space = post_residual < next_item_size && next_item_size > 0;
    let tiny_gap = post_residual > 0 && post_residual < 10;

    if dead_space {
        score += 120.0 + (10.0 - post_residual.min(10) as f64) * 3.0;
    }
    if tiny_gap {
        score += 25.0;
    }

    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
    score -= fill_ratio * 18.0;

    let mean_gap_penalty = (mean_residual - post_residual as f64).max(0.0);
    score -= mean_gap_penalty * 0.35;

    let pressure = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    score += (open_bins_count as f64) * (2.0 + pressure * 4.0);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

