pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let mean = mean_residual.max(0.0);
    let lookahead = next_item_size as f64;
    let dead_space_threshold = lookahead.max(1.0);

    // Residuals below a likely next item are difficult to reuse.
    if (post_residual as f64) < dead_space_threshold {
        score += (dead_space_threshold - post_residual as f64) * 2.25;
    }

    // Exact closure is ideal, while small nonzero remnants are costly.
    if post_residual == 0 {
        score -= 8.0;
    } else if (post_residual as f64) < 10.0 {
        score += 3.0;
    }

    // Avoid placements substantially worse than the average open-bin residual.
    let residual_excess = post_residual as f64 - mean;
    if residual_excess > 0.0 {
        score += residual_excess * 0.85;
    } else {
        score += residual_excess * 0.20;
    }

    // Pressure to consolidate into existing bins rises when many bins are open.
    let pressure = (open_bins_count as f64).max(0.0);
    score += pressure * 0.55;

    // Favor the final fitting bin unless doing so leaves poor dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Early in the stream, preserve flexibility; later, consolidate more aggressively.
    score += (1.0 - progress) * (post_residual as f64) * 0.12;

    // A new bin has no dead space, but it increases fragmentation pressure.
    if bin_residual == bin_capacity {
        score += pressure * 0.35 + 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let min_item = 1u32;
    let usable_threshold = min_item;

    if post_residual < usable_threshold {
        score += 1000.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 250.0 + (next_item_size - post_residual) as f64 * 8.0;
    }

    let dead_gap_penalty = if post_residual == 0 {
        0.0
    } else {
        (post_residual as f64 / bin_capacity as f64).powi(2) * 120.0
    };
    score += dead_gap_penalty;

    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score -= open_pressure * 6.0;

    if fitting_bins_count <= 1 {
        score -= 35.0;
    }

    let utilization = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= utilization * utilization * 45.0;

    let proximity = (step_index as f64 + 1.0) / total_items.max(1) as f64;
    score -= proximity * 4.0;

    score -= (mean_residual - post_residual as f64).abs() * 1.5;

    score
}
